/**
 * Worker entry (decision 0018, design D2): the OpenNext handler for every
 * request, plus scheduled() for the two Cron Triggers in wrangler.jsonc.
 *
 * Type-checked by worker/tsconfig.json (Workers types), not by the Next.js
 * tsconfig, which excludes this directory.
 */
// @ts-expect-error generated by `opennextjs-cloudflare build`; it has no type declarations.
import openNextHandler from "../.open-next/worker.js";
import { cronRoutesFor } from "../lib/cron/schedule";
import { runCronRoutes } from "../lib/cron/run";

/** The bindings and vars this entry reads; the app's full shape is AppEnv in lib/db/env.ts. */
interface WorkerEnv {
  CRON_SHARED_SECRET?: string;
}

const handler = openNextHandler as ExportedHandler<WorkerEnv>;

export default {
  fetch(request, env, ctx) {
    return handler.fetch!(request, env, ctx);
  },

  async scheduled(controller, env, ctx) {
    const routes = cronRoutesFor(controller.cron, new Date(controller.scheduledTime));
    await runCronRoutes({
      routes,
      // Requests go straight to the fetch handler above; the origin is never resolved.
      origin: "https://poke-memory.internal",
      secret: env.CRON_SHARED_SECRET,
      // The cron request is built in-process, so it has no incoming `cf` object.
      fetchRoute: (request) =>
        Promise.resolve(
          handler.fetch!(request as Request<unknown, IncomingRequestCfProperties>, env, ctx),
        ),
      waitUntil: (promise) => ctx.waitUntil(promise),
    });
  },
} satisfies ExportedHandler<WorkerEnv>;
